/// What a node is that isn't an SSH server, for messages: "an RDP" (issue #3)
/// or "a telnet" (#179); `None` for an SSH server.
fn non_ssh_kind(protocol: Option<&str>) -> Option<&'static str> {
    match protocol {
        Some("rdp") => Some("an RDP"),
        Some("telnet") => Some("a telnet"),
        Some("vnc") => Some("a VNC"),
        _ => None,
    }
}

/// What a node is: `None` (or "ssh") for an SSH server, "rdp" for an RDP
/// server (issue #3), "telnet" for a telnet one (#179), "vnc" for a VNC one.
/// Written through its own command, like set_server_jump_host. Unchanged
/// values aren't written, so they don't stamp the row for sync.
#[tauri::command]
async fn set_server_protocol(state: tauri::State<'_, DbState>, id: i32, value: Option<String>) -> Result<(), String> {
    let value: Option<&str> = match value.as_deref() {
        None | Some("ssh") => None,
        Some("rdp") => Some("rdp"),
        Some("telnet") => Some("telnet"),
        Some("vnc") => Some("vnc"),
        Some(other) => return Err(format!("[DATABASE] SERVER_PROTOCOL_UNKNOWN: {other}")),
    };
    let conn_guard = state.conn.lock().map_err(|_| "[STATE] LOCK_FAILED")?;
    let conn = conn_guard.as_ref().ok_or("[STATE] DATABASE_NOT_INITIALIZED")?;
    let changed = conn.execute(
        "UPDATE servers SET protocol=?1 WHERE id=?2 AND protocol IS NOT ?1",
        rusqlite::params![value, id],
    ).map_err(|e| format!("[DATABASE] SERVER_PROTOCOL_FAILED: {}", e))?;
    drop(conn_guard);
    if changed > 0 {
        save_vault_internal(&state)?;
    }
    Ok(())
}

/// Duplicate a server row verbatim — including credentials linkage, tunnels,
/// mirrors, proxy config, colour. The clone gets a "{name} (copy)" suffix so
/// it shows up beside the original in the grid; everything else is identical
/// so the user can connect to the same target with a different label or
/// tweak one field without retyping the rest.
#[tauri::command]
async fn clone_server(state: tauri::State<'_, DbState>, id: i32) -> Result<i64, String> {
    let conn_guard = state.conn.lock().map_err(|_| "[STATE] LOCK_FAILED")?;
    let conn = conn_guard.as_ref().ok_or("[STATE] DATABASE_NOT_INITIALIZED")?;
    let affected = conn.execute(
        "INSERT INTO servers (name, host, port, username, password, credential_id, folder_id, proxy_type, proxy_host, proxy_port, tunnels, auth_type, key_id, autostart, mirrors, color, notes, run_on_connect, jump_host_id, protocol)
         SELECT name || ' (copy)', host, port, username, password, credential_id, folder_id, proxy_type, proxy_host, proxy_port, tunnels, auth_type, key_id, 0, mirrors, color, notes, run_on_connect, jump_host_id, protocol
         FROM servers WHERE id = ?1",
        rusqlite::params![id],
    ).map_err(|e| format!("[DATABASE] SERVER_CLONE_FAILED: {}", e))?;
    if affected == 0 {
        return Err(format!("[DATABASE] SERVER_CLONE_FAILED: no row with id {}", id));
    }
    let new_id = conn.last_insert_rowid();
    // Place the clone at the bottom of its folder's manual order (the INSERT
    // above doesn't copy `position`, so without this it would default to 0 and
    // jump to the top). Same append logic as add_server, folder taken from the
    // clone's own row.
    let _ = conn.execute(
        "UPDATE servers SET position = COALESCE((SELECT MAX(position) FROM servers s2 WHERE s2.id != servers.id AND s2.folder_id IS servers.folder_id), -1) + 1 WHERE id = ?1",
        rusqlite::params![new_id],
    );
    // What is held on the original (a command or a forward a co-member put
    // there) is held on the copy too.
    if let (Some(from), Some(to)) = (approvals::server_uuid(conn, i64::from(id)), approvals::server_uuid(conn, new_id)) {
        let _ = approvals::copy_held(conn, &from, &to);
    }
    drop(conn_guard);
    save_vault_internal(&state)?;
    Ok(new_id)
}

#[tauri::command]
async fn delete_server(
    state: tauri::State<'_, DbState>,
    map: tauri::State<'_, MonitorMap>,
    id: i32,
) -> Result<(), String> {
    // Stop the poller BEFORE the row goes away. The monitor_configs row does
    // cascade-delete with the server, but that only removes the config — the
    // spawned poller lives in MonitorMap and would keep opening SSH connections
    // to the host on its interval, using credentials the user just deleted.
    // Worse, it becomes unreachable: monitor_list JOINs servers, so the node
    // vanishes from the UI and monitor_remove (the only other caller of
    // stop_monitor) can no longer be invoked for it. Only an app restart
    // stopped it.
    monitor::stop_monitor(map.inner().clone(), id).await;

    let conn_guard = state.conn.lock().map_err(|_| "[STATE] LOCK_FAILED")?;
    let conn = conn_guard.as_ref().ok_or("[STATE] DATABASE_NOT_INITIALIZED")?;

    conn.execute("DELETE FROM servers WHERE id=?1", rusqlite::params![id])
        .map_err(|e| format!("[DATABASE] SERVER_DELETE_FAILED: {}", e))?;

    drop(conn_guard);
    save_vault_internal(&state)?;
    Ok(())
}

#[tauri::command]
async fn get_servers(state: tauri::State<'_, DbState>) -> Result<Vec<serde_json::Value>, String> {
    let conn_guard = state.conn.lock().map_err(|_| "[STATE] LOCK_FAILED")?;
    let conn = conn_guard.as_ref().ok_or("[STATE] DATABASE_NOT_INITIALIZED")?;
    // Secrets stay server-side: this listing returns `has_password` instead
    // of the plaintext column, so the password never crosses the IPC bridge
    // unless someone explicitly invokes `reveal_server_password`. The edit
    // panel calls reveal on open, but the cards / sidebar / quick-connect
    // grid never see the plaintext.
    // ORDER BY (position, id): `position` is the manual drag-to-reorder rank
    // (default 0 for never-reordered rows), and id breaks ties so the order is
    // stable and, before any reorder, identical to the old rowid order.
    let mut stmt = conn.prepare("SELECT id, name, host, port, username, password, credential_id, folder_id, proxy_type, proxy_host, proxy_port, tunnels, auth_type, key_id, autostart, mirrors, color, notes, run_on_connect, jump_host_id, updated_at, edited_by, position, uuid, protocol FROM servers ORDER BY position, id")
        .map_err(|e| format!("[DATABASE] PREPARE_FAILED: {}", e))?;

    let rows = stmt.query_map([], |row| {
        let pw: Option<String> = row.get::<_, Option<String>>(5)?;
        Ok(json!({
            "id": row.get::<_, i32>(0)?,
            "name": row.get::<_, String>(1)?,
            "host": row.get::<_, String>(2)?,
            "port": row.get::<_, i32>(3)?,
            "username": row.get::<_, Option<String>>(4)?.unwrap_or_default(),
            "has_password": pw.as_deref().map(|s| !s.is_empty()).unwrap_or(false),
            "credential_id": row.get::<_, Option<i32>>(6)?,
            "folder_id": row.get::<_, Option<i32>>(7)?,
            "proxy_type": row.get::<_, Option<String>>(8)?.unwrap_or_else(|| "none".to_string()),
            "proxy_host": row.get::<_, Option<String>>(9)?.unwrap_or_default(),
            "proxy_port": row.get::<_, Option<i32>>(10)?.unwrap_or(1080),
            "tunnels": row.get::<_, Option<String>>(11)?.unwrap_or_else(|| "[]".to_string()),
            "auth_type": row.get::<_, Option<String>>(12)?.unwrap_or_else(|| "vault".to_string()),
            "key_id": row.get::<_, Option<i32>>(13)?,
            "autostart": row.get::<_, i32>(14).unwrap_or(0) != 0,
            "mirrors": row.get::<_, Option<String>>(15)?.unwrap_or_else(|| "[]".to_string()),
            "color": row.get::<_, Option<String>>(16)?,
            "notes": row.get::<_, Option<String>>(17)?.unwrap_or_default(),
            "run_on_connect": row.get::<_, Option<String>>(18)?.unwrap_or_default(),
            "jump_host_id": row.get::<_, Option<i32>>(19)?,
            // Attribution: HLC stamp (encodes last-edit time) + who last edited.
            "updated_at": row.get::<_, Option<String>>(20)?,
            "edited_by": row.get::<_, Option<String>>(21)?,
            // Manual drag-to-reorder rank (see ORDER BY above).
            "position": row.get::<_, i64>(22).unwrap_or(0),
            // The sync id: the same on every device, and unlike `id` never
            // reused by another profile's server. Keys this device's own
            // per-server settings (see src/util/shellSync.ts).
            "uuid": row.get::<_, Option<String>>(23)?,
            // "ssh", "rdp" (issue #3), "telnet" (#179) or "vnc"; NULL in the
            // table (and anything a newer version may add) is an SSH server.
            "protocol": match row.get::<_, Option<String>>(24)?.as_deref() {
                Some("rdp") => "rdp",
                Some("telnet") => "telnet",
                Some("vnc") => "vnc",
                _ => "ssh",
            },
        }))
    }).map_err(|e| format!("[DATABASE] QUERY_MAPPING_FAILED: {}", e))?;

    // What this device holds back for each server until the user allows it:
    // a change someone else made in a shared profile (see approvals.rs).
    // Empty for every server of a personal profile.
    let mut held = approvals::held_by_server(conn);
    let mut list = Vec::new();
    for r in rows {
        let mut row = r.map_err(|e| format!("[DATABASE] ROW_FETCH_FAILED: {}", e))?;
        let items = row
            .get("uuid")
            .and_then(|u| u.as_str())
            .and_then(|u| held.remove(u))
            .unwrap_or_default();
        row["held"] = json!(items);
        list.push(row);
    }
    Ok(list)
}

/// Allow what this device held back for one server (see approvals.rs): the
/// given items, or all of its items when `items` is empty. A monitor already
/// polling that server picks up allowed commands at once, and allowed
/// forwards are no longer stopped in the server's session, so the next
/// connect starts them (as does the Start button now). Autostart counts from
/// the next unlock; the frontend types allowed on-connect commands itself.
#[tauri::command]
async fn allow_held(
    db_state: tauri::State<'_, DbState>,
    ssh: tauri::State<'_, SshState>,
    map: tauri::State<'_, MonitorMap>,
    server_id: i32,
    items: Vec<String>,
) -> Result<usize, String> {
    let (allowed, customs) = {
        let guard = db_state.conn.lock().map_err(|_| "[STATE] LOCK_FAILED")?;
        let conn = guard.as_ref().ok_or("[STATE] DATABASE_NOT_INITIALIZED")?;
        let uuid = approvals::server_uuid(conn, server_id as i64).ok_or("[SYNC] NO_SUCH_SERVER")?;
        let held = approvals::held_for(conn, &uuid);
        let allowed: Vec<String> = if items.is_empty() {
            held.into_iter().collect()
        } else {
            items.into_iter().filter(|i| held.contains(i)).collect()
        };
        if allowed.is_empty() {
            return Ok(0);
        }
        approvals::allow(conn, &uuid, &allowed)?;
        let customs = if allowed.iter().any(|i| i.starts_with("metric:")) {
            load_monitor_config(conn, server_id)
                .map(|(_, customs, _)| approvals::without_held_metrics(conn, Some(&uuid), customs))
        } else {
            None
        };
        (allowed, customs)
    };
    if let Some(customs) = customs {
        // Only a running poller takes the list; a stopped one reads it from
        // the database when it starts.
        let _ = monitor::set_custom_metrics(map.inner().clone(), server_id, customs).await;
    }
    if allowed.iter().any(|i| i.starts_with("tunnel:")) {
        let mut rules_by_session = ssh.session_tunnel_specs.lock().await;
        if let Some(rules) = rules_by_session.get_mut(&format!("session-{server_id}")) {
            for rule in rules.iter_mut().filter(|r| allowed.contains(&approvals::tunnel_item(r))) {
                rule.stopped = false;
            }
        }
    }
    save_vault_internal(&db_state)?;
    Ok(allowed.len())
}

#[tauri::command]
async fn get_ssh_keys(state: tauri::State<'_, DbState>) -> Result<Vec<serde_json::Value>, String> {
    let conn_guard = state.conn.lock().map_err(|_| "[STATE] LOCK_FAILED")?;
    let conn = conn_guard.as_ref().ok_or("[STATE] DATABASE_NOT_INITIALIZED")?;
    // Private key + passphrase do NOT cross IPC in the listing — only the
    // public key (which is safe by definition) and presence flags. The edit
    // sheet calls `reveal_ssh_key` when it needs the secrets to display.
    let mut stmt = conn.prepare("SELECT id, name, public_key, private_key, passphrase FROM ssh_keys").map_err(|e| e.to_string())?;
    let rows = stmt.query_map([], |row| {
        let priv_present: Option<String> = row.get::<_, Option<String>>(3)?;
        let pp_present: Option<String> = row.get::<_, Option<String>>(4)?;
        Ok(json!({
            "id": row.get::<_, i32>(0)?,
            "name": row.get::<_, String>(1)?,
            "public_key": row.get::<_, String>(2)?,
            "has_private_key": priv_present.as_deref().map(|s| !s.is_empty()).unwrap_or(false),
            "has_passphrase": pp_present.as_deref().map(|s| !s.is_empty()).unwrap_or(false),
        }))
    }).map_err(|e| e.to_string())?;
    
    let mut list = Vec::new();
    for r in rows {
        list.push(r.map_err(|e| format!("[DATABASE] ROW_FETCH_FAILED: {}", e))?);
    }
    Ok(list)
}

