/// One-shot inline auth bundle for "quick connect" — connecting to a host
/// without saving anything in the vault. Mirrors the subset of node fields
/// that the connection flow actually needs: address, identity, and either
/// a password or a PEM key body. Proxy + tunnel auto-start are deliberately
/// omitted; the user can save a real node if they need those.
#[derive(Debug, Clone, serde::Deserialize)]
struct QuickAuth {
    host: String,
    port: i32,
    username: String,
    #[serde(default)]
    password: Option<String>,
    #[serde(default)]
    private_key: Option<String>,
    #[serde(default)]
    passphrase: Option<String>,
}

/// Largest number of connect-time secret prompts (a missing password or key
/// passphrase) shown before giving up on an auth method, per issue #30.
const MAX_SECRET_PROMPTS: u32 = 3;

/// Which field of the per-tab `ssh_manager::PromptedSecrets` cache a prompting
/// auth call reads and writes.
#[derive(Clone, Copy)]
enum SecretSlot {
    Password,
    Passphrase,
    JumpPassword,
    JumpPassphrase,
    Username,
    JumpUsername,
}

/// The tab a connection belongs to. A dedicated `::sftp` / `::fwd` secondary
/// shares its parent tab's prompted-secret cache, so the suffix is stripped to
/// key the cache by the base session id. A plain primary id is returned as-is.
fn base_session_id(session_id: &str) -> &str {
    if let Some(base) = session_id.strip_suffix("::sftp").or_else(|| session_id.strip_suffix("::fwd")) {
        return base;
    }
    // A terminal that logs in on its own (issue #230): `<tab>::term-<terminal>`.
    match session_id.split_once("::term-") {
        Some((base, terminal)) if !base.is_empty() && !terminal.is_empty() => base,
        _ => session_id,
    }
}

/// How many times in a row a server may start a keyboard-interactive round with
/// nothing to answer before the method is given up on (a real one has a
/// banner, or two).
const MAX_EMPTY_KBI_ROUNDS: u32 = 20;

/// A host an HTTP proxy is asked to CONNECT to. It goes into the request line,
/// so one with a CR or LF in it would end that line and let the rest be a
/// second request to the proxy: the host comes from the saved server, which a
/// co-member of a shared profile can write. Names (any script), IPv4 and
/// bracketed IPv6 pass; controls, spaces and what has no place in a host don't.
pub(crate) fn http_connect_host_ok(host: &str) -> bool {
    !host.is_empty()
        && host.len() <= 253
        && host.chars().all(|c| c.is_alphanumeric() || matches!(c, '.' | '-' | '_' | ':' | '[' | ']' | '%'))
}

/// Why turning a stored private key into a usable keypair failed, split so the
/// connect path can tell a key that merely needs a passphrase we don't have
/// (worth asking the user for) from one that is broken regardless (no prompt
/// will fix it).
pub(crate) enum KeyDecodeError {
    /// Encrypted key whose supplied passphrase was missing, empty or wrong.
    NeedsPassphrase,
    /// Unparseable or unsupported key — the wrapped string is a human message.
    Malformed(String),
}

/// Decode `private_key` with `passphrase`, classifying any failure. `\r\n` is
/// normalised first (keys pasted on Windows) and an empty passphrase is treated
/// as none. "Is the key encrypted?" is answered from the key itself (the
/// OpenSSH header's `is_encrypted()`, a legacy `Proc-Type: 4,ENCRYPTED` PEM, or
/// an encrypted PKCS#8 one) — the same checks `load_key_from_disk` uses — so a
/// wrong passphrase is reported as `NeedsPassphrase` rather than `Malformed`.
/// The most bcrypt rounds an OpenSSH private key may ask for. `ssh-keygen`
/// defaults to 16 and never writes more than a few hundred even when told to;
/// 1024 leaves generous headroom while keeping a decode bounded to a fraction
/// of a second, so a key can't make decoding hang.
const MAX_KEY_KDF_ROUNDS: u32 = 1024;

/// What a key's passphrase may cost to try, for the formats that name the cost
/// in the file: the key is read with the passphrase it was saved with (a synced
/// key brings its own), and what the file asks for is run as it says. Numbers
/// far past what any tool writes would pin a thread for hours, or ask for
/// more memory than there is, which ends the whole app.
const MAX_PBKDF2_ITERATIONS: u64 = 2_000_000; // OpenSSL writes 2048..600000
const MAX_SCRYPT_BYTES: u64 = 256 * 1024 * 1024; // 128 * N * r; OpenSSL's default is 16 MB
const MAX_SCRYPT_PARALLEL: u64 = 16;
const MAX_PPK_ARGON2_KIB: u64 = 256 * 1024; // PuTTYgen writes 8192 (8 MB)
const MAX_PPK_ARGON2_WORK: u64 = 64 * 1024 * 1024; // memory (KiB) times passes; PuTTYgen: about 100000
const MAX_PPK_ARGON2_LANES: u64 = 16;

/// One DER element at the start of `input`: its tag, its content and what
/// follows it. `None` for anything that isn't well formed or runs past the end.
fn der_next(input: &[u8]) -> Option<(u8, &[u8], &[u8])> {
    let tag = *input.first()?;
    let first = *input.get(1)?;
    let (len, header) = if first < 0x80 {
        (first as usize, 2)
    } else {
        let n = (first & 0x7f) as usize;
        if n == 0 || n > 4 {
            return None;
        }
        let mut len = 0usize;
        for i in 0..n {
            len = len.checked_mul(256)?.checked_add(*input.get(2 + i)? as usize)?;
        }
        (len, 2 + n)
    };
    let end = header.checked_add(len)?;
    Some((tag, input.get(header..end)?, &input[end..]))
}

/// A DER INTEGER as an unsigned number; one that doesn't fit counts as the largest.
fn der_uint(content: &[u8]) -> u64 {
    let mut digits = content;
    while digits.len() > 1 && digits[0] == 0 {
        digits = &digits[1..];
    }
    if digits.len() > 8 {
        u64::MAX
    } else {
        digits.iter().fold(0u64, |acc, &b| (acc << 8) | u64::from(b))
    }
}

enum Pbes2Kdf {
    Pbkdf2 { iterations: u64 },
    Scrypt { n: u64, r: u64, p: u64 },
}

/// The key derivation named by a PKCS#8 `EncryptedPrivateKeyInfo` (PBES2), read
/// from its DER without the passphrase. `None` when it is anything else.
fn pbes2_kdf(der: &[u8]) -> Option<Pbes2Kdf> {
    const OID_PBES2: &[u8] = &[0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x05, 0x0d];
    const OID_PBKDF2: &[u8] = &[0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x05, 0x0c];
    const OID_SCRYPT: &[u8] = &[0x2b, 0x06, 0x01, 0x04, 0x01, 0xda, 0x47, 0x04, 0x0b];
    let (_, info, _) = der_next(der)?; // EncryptedPrivateKeyInfo
    let (_, algorithm, _) = der_next(info)?; // its AlgorithmIdentifier
    let (tag, oid, rest) = der_next(algorithm)?;
    if tag != 0x06 || oid != OID_PBES2 {
        return None;
    }
    let (_, pbes2, _) = der_next(rest)?; // PBES2-params
    let (_, kdf, _) = der_next(pbes2)?; // keyDerivationFunc
    let (tag, oid, rest) = der_next(kdf)?;
    if tag != 0x06 {
        return None;
    }
    let (_, params, _) = der_next(rest)?;
    let (tag, _salt, rest) = der_next(params)?;
    let (int_tag, first, rest) = der_next(rest)?;
    if tag != 0x04 || int_tag != 0x02 {
        return None;
    }
    if oid == OID_PBKDF2 {
        return Some(Pbes2Kdf::Pbkdf2 { iterations: der_uint(first) });
    }
    if oid == OID_SCRYPT {
        let (r_tag, r, rest) = der_next(rest)?;
        let (p_tag, p, _) = der_next(rest)?;
        if r_tag != 0x02 || p_tag != 0x02 {
            return None;
        }
        return Some(Pbes2Kdf::Scrypt { n: der_uint(first), r: der_uint(r), p: der_uint(p) });
    }
    None
}

/// The Argon2 settings in the header of a PuTTY `.ppk` key: memory (KiB),
/// passes, lanes. `None` unless all three are there.
fn ppk_argon2(text: &str) -> Option<(u64, u64, u64)> {
    let (mut memory, mut passes, mut lanes) = (None, None, None);
    for line in text.lines() {
        if let Some((key, value)) = line.split_once(':') {
            let value = value.trim().parse::<u64>().ok();
            match key.trim() {
                "Argon2-Memory" => memory = value,
                "Argon2-Passes" => passes = value,
                "Argon2-Parallelism" => lanes = value,
                _ => {}
            }
        }
    }
    Some((memory?, passes?, lanes?))
}

/// Refuse a private key that asks for more work to unlock than a real key ever
/// would, before the expensive derivation runs. What it asks for is in the
/// key's cleartext envelope, read here without the passphrase: the bcrypt
/// rounds of an OpenSSH key, the Argon2 settings of a PuTTY `.ppk`, the PBKDF2
/// iterations or scrypt cost of an encrypted PKCS#8 key. Anything else (a
/// legacy PEM key, whose derivation is a hash or two) parses past this.
fn guard_key_kdf_cost(pem: &str) -> Result<(), KeyDecodeError> {
    let too_costly = |what: String| {
        KeyDecodeError::Malformed(format!(
            "this key asks for far more work to unlock than a real key needs ({what}); re-save it with a lower cost (an OpenSSH key: `ssh-keygen -p -f <keyfile>`)"
        ))
    };
    if let Ok(key) = ssh_key::PrivateKey::from_openssh(pem.trim()) {
        if let ssh_key::Kdf::Bcrypt { rounds, .. } = key.kdf() {
            if *rounds > MAX_KEY_KDF_ROUNDS {
                return Err(KeyDecodeError::Malformed(format!(
                    "this key asks for {rounds} key-derivation rounds — far more than a real key needs (limit {MAX_KEY_KDF_ROUNDS}); re-save it with `ssh-keygen -p -f <keyfile>`"
                )));
            }
        }
        return Ok(());
    }
    if pem.trim_start().starts_with("PuTTY-User-Key-File-") {
        if let Some((kib, passes, lanes)) = ppk_argon2(pem) {
            if kib > MAX_PPK_ARGON2_KIB || kib.saturating_mul(passes) > MAX_PPK_ARGON2_WORK || lanes > MAX_PPK_ARGON2_LANES {
                return Err(too_costly(format!("Argon2: {kib} KiB, {passes} passes, {lanes} lanes")));
            }
        }
        return Ok(());
    }
    if pem_private_key_header(pem) == "-----BEGIN ENCRYPTED PRIVATE KEY-----" {
        use base64::{engine::general_purpose::STANDARD, Engine as _};
        let body: String = pem
            .lines()
            .map(str::trim)
            .skip_while(|l| !l.starts_with("-----BEGIN "))
            .skip(1)
            .take_while(|l| !l.starts_with("-----END "))
            .collect();
        if let Some(kdf) = STANDARD.decode(body.as_bytes()).ok().as_deref().and_then(pbes2_kdf) {
            match kdf {
                Pbes2Kdf::Pbkdf2 { iterations } if iterations > MAX_PBKDF2_ITERATIONS => {
                    return Err(too_costly(format!("PBKDF2: {iterations} iterations")));
                }
                Pbes2Kdf::Scrypt { n, r, p } => {
                    let bytes = 128u64.saturating_mul(n).saturating_mul(r);
                    if bytes > MAX_SCRYPT_BYTES || p > MAX_SCRYPT_PARALLEL {
                        return Err(too_costly(format!("scrypt: N {n}, r {r}, p {p}")));
                    }
                }
                _ => {}
            }
        }
    }
    Ok(())
}

pub(crate) fn decode_private_key(
    private_key: &str,
    passphrase: Option<&str>,
) -> Result<russh::keys::PrivateKey, KeyDecodeError> {
    let normalized = private_key.replace("\r\n", "\n");
    // Refuse an absurd KDF cost BEFORE running it. An OpenSSH key names its
    // bcrypt round count in the clear, and decoding runs that many rounds; a
    // key synced by another member of a shared profile (or handed over by a
    // broken server) could set it to billions and pin a thread for ages on
    // every unlock. A real key uses tens of rounds — thousands is already far
    // past anything `ssh-keygen` makes.
    guard_key_kdf_cost(&normalized)?;
    let passphrase = passphrase.filter(|p| !p.is_empty());
    // russh decrypts the legacy PEM encryption only for RSA keys: an ECDSA key
    // encrypted that way decrypts and then fails the RSA decode whatever the
    // passphrase, so say so instead of asking for one three times.
    if is_legacy_encrypted_ec_pem(&normalized) {
        return Err(KeyDecodeError::Malformed(
            "this ECDSA key uses the legacy PEM encryption, which Submarine can only read for RSA keys; \
             re-save it in OpenSSH format with `ssh-keygen -p -f <keyfile>`"
                .into(),
        ));
    }
    // russh decrypts a legacy PKCS#1 PEM key encrypted the PKCS#5 way only with
    // AES-128-CBC. Another cipher — DES-EDE3 (PuTTYgen's OpenSSH export,
    // `openssl -des3`) or AES-256 — can't be read whatever the passphrase, so
    // say so instead of asking for one three times.
    if normalized.contains("Proc-Type: 4,ENCRYPTED") && !normalized.contains("DEK-Info: AES-128-CBC,") {
        return Err(KeyDecodeError::Malformed(
            "this key uses a legacy PEM encryption Submarine can't read (only AES-128-CBC); \
             re-save it in OpenSSH format with `ssh-keygen -p -f <keyfile>`"
                .into(),
        ));
    }
    // An unencrypted SEC1 / PKCS#8 key is read without the passphrase: russh's
    // PKCS#8 reader takes any passphrase it is handed to mean "this key is
    // encrypted" and fails, so one saved with such a key would break it.
    let header = pem_private_key_header(&normalized);
    let plain_pem = header == "-----BEGIN PRIVATE KEY-----" || header == "-----BEGIN EC PRIVATE KEY-----";
    let passphrase = if plain_pem { None } else { passphrase };
    match russh::keys::decode_secret_key(&normalized, passphrase) {
        Ok(key) => Ok(key),
        // The OpenSSH decoder reports this when an encrypted key is handed no
        // password at all.
        Err(russh::keys::Error::KeyIsEncrypted) => Err(KeyDecodeError::NeedsPassphrase),
        Err(e) => {
            // Decode failed with a passphrase in hand. If the key is an
            // encrypted one, the passphrase was wrong; otherwise it is a
            // genuinely unusable key. Encrypted means an OpenSSH key whose
            // header says so, a legacy PKCS#1 PEM key encrypted the PKCS#5 way
            // (`Proc-Type: 4,ENCRYPTED`, which russh decrypts) — a wrong
            // passphrase there fails deep in the RSA decode, not with
            // KeyIsEncrypted, so without this check a typo ended the attempt
            // as "failed to parse" instead of asking again — or an encrypted
            // PKCS#8 key, which fails the same way with no passphrase at all.
            if private_key_is_encrypted(&normalized) {
                Err(KeyDecodeError::NeedsPassphrase)
            } else {
                Err(KeyDecodeError::Malformed(e.to_string()))
            }
        }
    }
}

/// `&mut` accessor for one slot of a `PromptedSecrets`, so the cache get/set/
/// clear helpers don't each repeat the match.
fn prompted_secret_slot(
    secrets: &mut ssh_manager::PromptedSecrets,
    slot: SecretSlot,
) -> &mut Option<zeroize::Zeroizing<String>> {
    match slot {
        SecretSlot::Password => &mut secrets.password,
        SecretSlot::Passphrase => &mut secrets.passphrase,
        SecretSlot::JumpPassword => &mut secrets.jump_password,
        SecretSlot::JumpPassphrase => &mut secrets.jump_passphrase,
        SecretSlot::Username => &mut secrets.username,
        SecretSlot::JumpUsername => &mut secrets.jump_username,
    }
}

type PromptedSecretsMap =
    std::sync::Arc<tokio::sync::Mutex<std::collections::HashMap<String, ssh_manager::PromptedSecrets>>>;
type KbiTxs = std::sync::Arc<
    tokio::sync::Mutex<
        std::collections::HashMap<String, tokio::sync::oneshot::Sender<Option<Vec<String>>>>,
    >,
>;

/// A copy of one cached secret for `base`, or `None` when absent.
async fn cache_get_secret(
    cache: &PromptedSecretsMap,
    base: &str,
    slot: SecretSlot,
) -> Option<zeroize::Zeroizing<String>> {
    let mut map = cache.lock().await;
    map.get_mut(base).and_then(|s| prompted_secret_slot(s, slot).clone())
}

/// Remember an accepted secret for `base` so reconnects / secondaries reuse it.
async fn cache_store_secret(
    cache: &PromptedSecretsMap,
    base: &str,
    slot: SecretSlot,
    value: zeroize::Zeroizing<String>,
) {
    let mut map = cache.lock().await;
    let entry = map.entry(base.to_string()).or_default();
    *prompted_secret_slot(entry, slot) = Some(value);
}

/// Forget one cached secret for `base` (e.g. the server just rejected it).
async fn cache_clear_secret(cache: &PromptedSecretsMap, base: &str, slot: SecretSlot) {
    let mut map = cache.lock().await;
    if let Some(entry) = map.get_mut(base) {
        *prompted_secret_slot(entry, slot) = None;
    }
}

/// Where a connect-time secret came from, which decides what happens to it once
/// the server answers: a `Given` one (the saved value) is never cached; a
/// `Cache` one is stored again on success and dropped on rejection; a `Prompt`
/// one — or the failed-screen `Override` — is stored once accepted. Caching an
/// accepted override is what lets the screen forget it after a successful
/// connect, so a mistyped one isn't sent first on every later attempt.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SecretSource {
    Given,
    Override,
    Cache,
    Prompt,
}

/// The secrets already in hand for one auth method, in the order they are
/// tried: the per-connect override (failed-screen box), then what the user
/// typed earlier this tab (cache), then the saved value. A cached value beats
/// the saved one: it only exists because the saved one was missing or rejected
/// earlier this tab. Empty values are dropped — an empty saved secret means
/// "ask when connecting".
fn secret_candidates(
    override_secret: Option<zeroize::Zeroizing<String>>,
    cached: Option<zeroize::Zeroizing<String>>,
    saved: Option<zeroize::Zeroizing<String>>,
) -> Vec<(zeroize::Zeroizing<String>, SecretSource)> {
    [
        (override_secret, SecretSource::Override),
        (cached, SecretSource::Cache),
        (saved, SecretSource::Given),
    ]
    .into_iter()
    .filter_map(|(secret, source)| secret.filter(|s| !s.is_empty()).map(|s| (s, source)))
    .collect()
}

/// Everything a connect-time secret prompt needs besides the SSH session: where
/// to show it (the keyboard-interactive modal of `session_id`, answered under
/// `nonce`) and where accepted secrets live (`cache`, under the tab's `base`
/// id). `allow_prompt` is false for the dedicated `::sftp` / `::fwd`
/// secondaries, which only ever reuse what the primary cached.
struct SecretPromptCtx<'a> {
    app: &'a tauri::AppHandle,
    session_id: &'a str,
    nonce: &'a str,
    kbi_txs: &'a KbiTxs,
    cache: &'a PromptedSecretsMap,
    base: &'a str,
    allow_prompt: bool,
    /// The connect attempt asking. A prompt is only shown while it's current
    /// (see ssh_manager::ConnectAttempt).
    attempt: &'a ssh_manager::ConnectAttempt,
    /// Set when the user cancels one of our prompts (or lets it time out).
    /// The caller then skips the keyboard-interactive fallback: on a typical
    /// OpenSSH + PAM server that fallback would immediately show the server's
    /// own "Password:" box, i.e. ask again for what the user just declined.
    /// Atomic because the context is borrowed across awaits in a spawned task.
    cancelled: std::sync::atomic::AtomicBool,
    /// The saved server whose password a prompt asks for: its prompt offers
    /// "Save password", and a password it got saved goes to it (or its saved
    /// login) once the login worked. None where there's nothing to save it to,
    /// or the login name was typed (see `save_offer`).
    save_to: Option<SaveTarget>,
    /// The ssh-agent for this login (see `AgentSlot`).
    agent: tokio::sync::Mutex<AgentSlot>,
    /// Set when an agent signature failed or timed out after the server had
    /// accepted the key. russh's session then waits for that signature and
    /// drops everything else, so no other method may run on it — the
    /// keyboard-interactive fallback included.
    session_unusable: std::sync::atomic::AtomicBool,
}

/// The ssh-agent for one login. Looked up the first time a step wants it, so a
/// login that works without one never touches an agent, and let go once the
/// login is over.
struct AgentSlot {
    looked: bool,
    agent: Option<agent_auth::AgentSession>,
    /// What `IdentityAgent` in `~/.ssh/config` says for this host, if it
    /// applies (see `ConfigTarget`).
    identity_agent: Option<ssh_config::IdentityAgent>,
    /// The key files `IdentityFile` / `CertificateFile` name for this host,
    /// offered before an agent's keys (see `try_config_identities`).
    identities: ConfigIdentities,
    identities_tried: bool,
}

impl AgentSlot {
    /// `use_agent` is the device's "Use keys from an ssh-agent" setting. Off,
    /// the slot starts as looked-and-none, so no agent is ever contacted. With
    /// `IdentitiesOnly yes` only the config's key files are used, as OpenSSH.
    fn new(
        use_agent: bool,
        identity_agent: Option<ssh_config::IdentityAgent>,
        identities: ConfigIdentities,
    ) -> tokio::sync::Mutex<Self> {
        let use_agent = use_agent && !identities.only;
        tokio::sync::Mutex::new(Self { looked: !use_agent, agent: None, identity_agent, identities, identities_tried: false })
    }
}

/// The key and certificate files `~/.ssh/config` names for a host, paths
/// expanded. Read from disk only when a login wants them.
#[derive(Clone, Default)]
struct ConfigIdentities {
    keys: Vec<String>,
    certs: Vec<String>,
    /// `IdentitiesOnly yes`.
    only: bool,
}

/// A node's display name. An imported node keeps its `~/.ssh/config` alias as
/// its name, so `Host` patterns are matched against it as well as the address.
fn server_display_name(conn: &rusqlite::Connection, server_id: i32) -> Option<String> {
    conn.query_row("SELECT name FROM servers WHERE id = ?1", [server_id], |row| row.get::<_, Option<String>>(0))
        .ok()
        .flatten()
}

/// Where one connection goes once `~/.ssh/config` has had its say: the
/// address and port an alias stands for (`HostName`, `Port`), and its `User`
/// for a node saved without a username. `config` keeps the rest (agent, key
/// files, proxy) for the steps that use it; `log` says what the config
/// changed or why something in it was skipped.
struct ConfigTarget {
    /// The address as saved (an alias, maybe): ProxyCommand's `%n`.
    original: String,
    host: String,
    port: u16,
    user: String,
    config: Option<ssh_config::HostConfig>,
    log: Vec<String>,
}

impl ConfigTarget {
    /// `~/.ssh/config` for a connection to `host:port` as `user` (blank =
    /// asked when connecting) for a node called `name`. Nothing changes when
    /// the device's switch is off, there's no config, or this is Android.
    async fn resolve(host: &str, port: u16, user: &str, name: Option<String>) -> Self {
        let user_given = user.trim();
        let lookup = ssh_config::Lookup {
            address: host.to_string(),
            name: name.filter(|n| !n.trim().is_empty()),
            user: Some(user_given.to_string()).filter(|u| !u.is_empty()),
        };
        let config = ssh_config::for_host(lookup).await;
        Self::apply(host, port, user, config)
    }

    fn apply(host: &str, port: u16, user: &str, config: Option<ssh_config::HostConfig>) -> Self {
        let mut t = Self {
            original: host.to_string(),
            host: host.to_string(),
            port,
            user: user.to_string(),
            config: None,
            log: Vec::new(),
        };
        let Some(c) = config else { return t };
        if let Some(h) = c.hostname.as_deref().filter(|h| !h.is_empty() && !h.eq_ignore_ascii_case(host)) {
            t.log.push(format!("~/.ssh/config: {host} is HostName {h}."));
            t.host = h.to_string();
        }
        if let Some(p) = c.port.filter(|&p| p != port) {
            t.log.push(format!("~/.ssh/config: Port {p} (in place of {port})."));
            t.port = p;
        }
        if user.trim().is_empty() {
            if let Some(u) = c.user.as_deref().map(str::trim).filter(|u| !u.is_empty()) {
                t.log.push(format!("~/.ssh/config: User {u}."));
                t.user = u.to_string();
            }
        }
        t.log.extend(c.notes.iter().cloned());
        t.config = Some(c);
        t
    }

    /// `IdentityAgent` for this host, resolved on this device.
    fn identity_agent(&self) -> Option<ssh_config::IdentityAgent> {
        self.config.as_ref()?.identity_agent.as_deref().map(ssh_config::resolve_identity_agent)
    }

    /// Paths from the config with their `~`, `${VAR}` and `%` tokens filled
    /// in for logging in as `user`; one that can't be is left out, logged.
    fn expand_paths(&mut self, values: &[String], what: &str, user: &str) -> Vec<String> {
        let mut out = Vec::new();
        for value in values {
            let tokens = ssh_config::PathTokens { host: &self.host, original: &self.original, port: self.port, user: user.trim() };
            match ssh_config::expand_path(value, &tokens) {
                Ok(path) => out.push(path),
                Err(why) => self.log.push(format!("~/.ssh/config: {what} {value} {why}; not used.")),
            }
        }
        out
    }

    /// `IdentityFile`, `CertificateFile` and `IdentitiesOnly` for this host.
    fn identities(&mut self, user: &str) -> ConfigIdentities {
        let Some(c) = self.config.clone() else { return ConfigIdentities::default() };
        let keys = self.expand_paths(&c.identity_files, "IdentityFile", user);
        let certs = self.expand_paths(&c.certificate_files, "CertificateFile", user);
        let only = c.identities_only == Some(true);
        if only && !keys.is_empty() {
            self.log.push("~/.ssh/config: IdentitiesOnly yes: only its IdentityFile keys are used, not an ssh-agent's.".into());
        }
        ConfigIdentities { keys, certs, only }
    }

    /// `UserKnownHostsFile` for this host, expanded; `None` for OpenSSH's
    /// defaults (~/.ssh/known_hosts, known_hosts2).
    fn known_hosts_files(&mut self, user: &str) -> Option<Vec<String>> {
        let files = self.config.as_ref()?.user_known_hosts_files.clone()?;
        let files: Vec<String> = files.into_iter().filter(|f| !f.eq_ignore_ascii_case("none")).collect();
        Some(self.expand_paths(&files, "UserKnownHostsFile", user))
    }

    /// `HostKeyAlgorithms` for this host, as written.
    fn host_key_algorithms(&self) -> Option<String> {
        self.config.as_ref()?.host_key_algorithms.clone()
    }

    /// `ProxyCommand` / `ProxyJump` for this host, unless the server has its
    /// own way there (a jump host, or a SOCKS / HTTP proxy), which wins; that
    /// case is logged.
    fn proxy(&mut self, own_route: Option<&str>) -> Option<ssh_config::Proxy> {
        let proxy = self.config.as_ref()?.proxy.clone()?;
        let kind = match &proxy {
            ssh_config::Proxy::Command(_) => "ProxyCommand",
            ssh_config::Proxy::Jump(_) => "ProxyJump",
            ssh_config::Proxy::Disabled => return None,
        };
        if let Some(route) = own_route {
            self.log.push(format!("~/.ssh/config: {kind} isn't used: this server goes through its own {route}."));
            return None;
        }
        Some(proxy)
    }
}

/// A jump host's transport: TCP, a ProxyCommand, or a channel through the
/// previous hop.
enum HopStream {
    Tcp(tokio::net::TcpStream),
    Command(proxy_command::ProxyStream),
    Channel(tunnel::DrainedChannelStream),
}

impl tokio::io::AsyncRead for HopStream {
    fn poll_read(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        buf: &mut tokio::io::ReadBuf<'_>,
    ) -> std::task::Poll<std::io::Result<()>> {
        match self.get_mut() {
            HopStream::Tcp(s) => std::pin::Pin::new(s).poll_read(cx, buf),
            HopStream::Command(s) => std::pin::Pin::new(s).poll_read(cx, buf),
            HopStream::Channel(s) => std::pin::Pin::new(s).poll_read(cx, buf),
        }
    }
}

impl tokio::io::AsyncWrite for HopStream {
    fn poll_write(
        self: std::pin::Pin<&mut Self>,
        cx: &mut std::task::Context<'_>,
        buf: &[u8],
    ) -> std::task::Poll<std::io::Result<usize>> {
        match self.get_mut() {
            HopStream::Tcp(s) => std::pin::Pin::new(s).poll_write(cx, buf),
            HopStream::Command(s) => std::pin::Pin::new(s).poll_write(cx, buf),
            HopStream::Channel(s) => std::pin::Pin::new(s).poll_write(cx, buf),
        }
    }
    fn poll_flush(self: std::pin::Pin<&mut Self>, cx: &mut std::task::Context<'_>) -> std::task::Poll<std::io::Result<()>> {
        match self.get_mut() {
            HopStream::Tcp(s) => std::pin::Pin::new(s).poll_flush(cx),
            HopStream::Command(s) => std::pin::Pin::new(s).poll_flush(cx),
            HopStream::Channel(s) => std::pin::Pin::new(s).poll_flush(cx),
        }
    }
    fn poll_shutdown(self: std::pin::Pin<&mut Self>, cx: &mut std::task::Context<'_>) -> std::task::Poll<std::io::Result<()>> {
        match self.get_mut() {
            HopStream::Tcp(s) => std::pin::Pin::new(s).poll_shutdown(cx),
            HopStream::Command(s) => std::pin::Pin::new(s).poll_shutdown(cx),
            HopStream::Channel(s) => std::pin::Pin::new(s).poll_shutdown(cx),
        }
    }
}

/// Run `command` (ProxyCommand from ~/.ssh/config) for a connection to
/// `target` and return it as the transport; its standard error goes to the
/// connect log of `session_id` while `attempt` is current.
fn start_proxy_command(
    app: &tauri::AppHandle,
    session_id: &str,
    attempt: &ssh_manager::ConnectAttempt,
    command: &str,
    target: &ConfigTarget,
    user: &str,
) -> Result<(proxy_command::ProxyStream, proxy_command::Watch), String> {
    use tauri::Emitter;
    let tokens = proxy_command::Tokens { host: &target.host, original: &target.original, port: target.port, user: user.trim() };
    let expanded = proxy_command::expand(command, &tokens)
        .map_err(|why| format!("ProxyCommand in ~/.ssh/config {why}, so it wasn't run."))?;
    let app = app.clone();
    let session_id = session_id.to_string();
    let attempt = attempt.clone();
    proxy_command::spawn(&expanded, move |line| {
        println!("[LOG-{}] {}", session_id, line);
        if attempt.is_current_now() {
            let _ = app.emit(&format!("session-log-{}", session_id), serde_json::json!({"msg": line, "type": "info"}));
        }
    })
}

/// Turn the device's "Use settings from ~/.ssh/config" switch on or off. The
/// page calls this at start and whenever the switch changes; it's on until
/// then.
#[tauri::command]
fn set_use_ssh_config(enabled: bool) {
    ssh_config::set_enabled(enabled);
}

/// Whether an ssh-agent holding at least one key is running on this device.
/// Looks only once per login.
async fn agent_available(ctx: &SecretPromptCtx<'_>) -> bool {
    let mut slot = ctx.agent.lock().await;
    if !slot.looked {
        slot.looked = true;
        let setting = slot.identity_agent.take();
        slot.agent = agent_auth::find_agent_for(setting, |m| ctx.log(&m, "info")).await;
        if let Some(agent) = &slot.agent {
            let n = agent.key_count();
            ctx.log(
                &format!("Found {} holding {} key{}.", agent.source, n, if n == 1 { "" } else { "s" }),
                "info",
            );
        }
    }
    slot.agent.is_some()
}

/// Offer ssh-agent keys for this login (see `agent_auth`). `Ok(None)` when no
/// agent with a key is running. An `Err` means an agent signature failed after
/// the server had accepted the key: the session can't run anything else, so
/// `session_unusable` is set and the caller must stop.
async fn try_agent_keys<H: russh::client::Handler>(
    session: &mut russh::client::Handle<H>,
    user: &str,
    which: agent_auth::Offer<'_>,
    already_offered: Option<&russh::keys::PublicKey>,
    ctx: &SecretPromptCtx<'_>,
) -> Result<Option<agent_auth::AgentOutcome>, russh::Error> {
    // The key files ~/.ssh/config names for this host come first: they're
    // what it says to use here (Teleport's certificate, say).
    if matches!(which, agent_auth::Offer::Rest) {
        if let Some(outcome @ (agent_auth::AgentOutcome::Authenticated | agent_auth::AgentOutcome::PartialSuccess { .. })) =
            try_config_identities(session, user, ctx).await?
        {
            return Ok(Some(outcome));
        }
    }
    if !agent_available(ctx).await {
        return Ok(None);
    }
    let mut slot = ctx.agent.lock().await;
    let Some(agent) = slot.agent.as_mut() else {
        return Ok(None);
    };
    if let Some(key) = already_offered {
        agent.mark_offered(key);
    }
    match agent_auth::offer_keys(session, user, agent, which, |m| ctx.log(&m, "info")).await {
        Ok(outcome) => Ok(Some(outcome)),
        Err(e) => {
            ctx.session_unusable.store(true, std::sync::atomic::Ordering::Relaxed);
            Err(e)
        }
    }
}

/// Whether this login has device keys to try before asking for a password:
/// key files from ~/.ssh/config not tried yet, or an ssh-agent with a key.
async fn device_keys_available(ctx: &SecretPromptCtx<'_>) -> bool {
    {
        let slot = ctx.agent.lock().await;
        if !slot.identities_tried && !slot.identities.keys.is_empty() {
            return true;
        }
    }
    agent_available(ctx).await
}

/// The largest key or certificate file read.
const MAX_KEY_FILE_BYTES: u64 = 256 * 1024;

fn read_small_file(path: &str) -> Result<String, String> {
    let meta = std::fs::metadata(path).map_err(|e| e.kind().to_string())?;
    if !meta.is_file() {
        return Err("isn't a file".into());
    }
    if meta.len() > MAX_KEY_FILE_BYTES {
        return Err("is too large to be a key".into());
    }
    std::fs::read_to_string(path).map_err(|e| e.to_string())
}

/// A certificate file, if it reads as one.
fn read_certificate(path: &str) -> Option<russh::keys::Certificate> {
    russh::keys::Certificate::from_openssh(read_small_file(path).ok()?.trim()).ok()
}

/// The private key in `text` (the file `path`), with its passphrase from
/// this tab's cache or asked for, as a saved key's is. `None` when it can't
/// be used (logged).
async fn decode_identity_file(text: &str, path: &str, ctx: &SecretPromptCtx<'_>) -> Option<russh::keys::PrivateKey> {
    let cache_base = format!("{}|idfile|{}", ctx.base, path);
    let mut passphrase = cache_get_secret(ctx.cache, &cache_base, SecretSlot::Passphrase).await;
    let mut from_cache = passphrase.is_some();
    let mut prompts = 0u32;
    loop {
        match decode_private_key(text, passphrase.as_ref().map(|p| p.as_str())) {
            Ok(key) => {
                if let Some(p) = passphrase {
                    if !from_cache {
                        cache_store_secret(ctx.cache, &cache_base, SecretSlot::Passphrase, p).await;
                    }
                }
                return Some(key);
            }
            Err(KeyDecodeError::NeedsPassphrase) => {
                if from_cache {
                    cache_clear_secret(ctx.cache, &cache_base, SecretSlot::Passphrase).await;
                    from_cache = false;
                }
                if !ctx.allow_prompt || prompts >= MAX_SECRET_PROMPTS {
                    ctx.log(&format!("IdentityFile {path} needs its passphrase; skipped."), "info");
                    return None;
                }
                let instructions = if prompts > 0 { "The passphrase didn't unlock the key. Please try again." } else { "" };
                match prompt_for_secret(ctx, &format!("Passphrase for key '{path}'"), instructions, false).await {
                    Some(typed) => {
                        prompts += 1;
                        passphrase = Some(typed);
                    }
                    None => {
                        ctx.log("Passphrase prompt cancelled or timed out.", "error");
                        return None;
                    }
                }
            }
            Err(KeyDecodeError::Malformed(why)) => {
                ctx.log(&format!("IdentityFile {path} can't be used: {why}"), "info");
                return None;
            }
        }
    }
}

/// Log in with the key files `IdentityFile` names in ~/.ssh/config, each with
/// its certificate first (from `CertificateFile`, or `<key>-cert.pub` next to
/// it), as OpenSSH does. Read from disk once per login. `Ok(None)` when there
/// are none (or they were tried already).
async fn try_config_identities<H: russh::client::Handler>(
    session: &mut russh::client::Handle<H>,
    user: &str,
    ctx: &SecretPromptCtx<'_>,
) -> Result<Option<agent_auth::AgentOutcome>, russh::Error> {
    use agent_auth::AgentOutcome;
    let (keys, certs) = {
        let mut slot = ctx.agent.lock().await;
        if slot.identities_tried || slot.identities.keys.is_empty() {
            return Ok(None);
        }
        slot.identities_tried = true;
        (slot.identities.keys.clone(), slot.identities.certs.clone())
    };
    let named_certs: Vec<(String, russh::keys::Certificate)> = certs
        .iter()
        .filter_map(|p| match read_certificate(p) {
            Some(c) => Some((p.clone(), c)),
            None => {
                ctx.log(&format!("CertificateFile {p} can't be read as a certificate; skipped."), "info");
                None
            }
        })
        .collect();
    let mut outcome = AgentOutcome::NothingToOffer;
    for path in keys {
        let text = match read_small_file(&path) {
            Ok(t) => t,
            Err(why) => {
                ctx.log(&format!("IdentityFile {path} can't be read ({why}); skipped."), "info");
                continue;
            }
        };
        let Some(key) = decode_identity_file(&text, &path, ctx).await else { continue };
        let public = key.public_key().clone();
        let key = std::sync::Arc::new(key);
        let mut with_certs: Vec<(String, russh::keys::Certificate)> =
            named_certs.iter().filter(|(_, c)| c.public_key() == public.key_data()).cloned().collect();
        let sibling = format!("{path}-cert.pub");
        if !with_certs.iter().any(|(p, _)| *p == sibling) {
            if let Some(c) = read_certificate(&sibling).filter(|c| c.public_key() == public.key_data()) {
                with_certs.push((sibling, c));
            }
        }
        let mut attempts: Vec<(String, Option<russh::keys::Certificate>)> =
            with_certs.into_iter().map(|(p, c)| (p, Some(c))).collect();
        attempts.push((path.clone(), None));
        for (label, cert) in attempts {
            let result = match cert {
                Some(cert) => {
                    ctx.log(&format!("Trying the certificate {label} (IdentityFile in ~/.ssh/config)..."), "info");
                    ssh_manager::authenticate_with_certificate(session, user, std::sync::Arc::clone(&key), cert).await?
                }
                None => {
                    ctx.log(&format!("Trying IdentityFile {label} from ~/.ssh/config..."), "info");
                    ssh_manager::authenticate_with_key_result(session, user, (*key).clone()).await?
                }
            };
            match result {
                russh::client::AuthResult::Success => {
                    ctx.log(&format!("Logged in with {label}."), "success");
                    return Ok(Some(AgentOutcome::Authenticated));
                }
                russh::client::AuthResult::Failure { .. } if session.is_closed() => return Err(russh::Error::Disconnect),
                russh::client::AuthResult::Failure { remaining_methods, partial_success: true } => {
                    return Ok(Some(AgentOutcome::PartialSuccess { remaining: remaining_methods }));
                }
                russh::client::AuthResult::Failure { remaining_methods, .. } => {
                    outcome = AgentOutcome::NotAccepted;
                    if !remaining_methods.contains(&russh::MethodKind::PublicKey) {
                        return Ok(Some(outcome));
                    }
                }
            }
        }
    }
    Ok(Some(outcome))
}

/// The agent's keys not offered yet, after the node's own credentials didn't
/// log in. `Ok(true)` once logged in; a partial success leaves the second
/// factor to the keyboard-interactive fallback, as with the node's own key.
async fn agent_keys_after<H: russh::client::Handler>(
    session: &mut russh::client::Handle<H>,
    user: &str,
    already_offered: Option<&russh::keys::PublicKey>,
    ctx: &SecretPromptCtx<'_>,
) -> Result<bool, russh::Error> {
    Ok(matches!(
        try_agent_keys(session, user, agent_auth::Offer::Rest, already_offered, ctx).await?,
        Some(agent_auth::AgentOutcome::Authenticated)
    ))
}

/// Let the ssh-agent go once the login is over.
async fn release_agent(ctx: &SecretPromptCtx<'_>) {
    ctx.agent.lock().await.agent = None;
}

impl SecretPromptCtx<'_> {
    /// Activity-log line for this connection. Never given a secret. A
    /// superseded attempt stays out of the tab's log (it would read as the
    /// newer attempt's).
    fn log(&self, msg: &str, ty: &str) {
        use tauri::Emitter;
        println!("[LOG-{}] {}", self.session_id, msg);
        if !self.attempt.is_current_now() {
            return;
        }
        let _ = self.app.emit(
            &format!("session-log-{}", self.session_id),
            serde_json::json!({"msg": msg, "type": ty}),
        );
    }

    /// Where a password typed now may be saved, and whether the tick starts
    /// on: off when this login also tried keys, an ssh-agent's or the ones
    /// ~/.ssh/config names for the host (a saved password would be used
    /// instead of them from then on).
    async fn save_offer(&self) -> Option<SaveTarget> {
        let to = self.save_to?;
        let keys = {
            let slot = self.agent.lock().await;
            slot.agent.is_some() || !slot.identities.keys.is_empty()
        };
        Some(SaveTarget { ticked: !keys, ..to })
    }
}

/// Ask the user for ONE value at connect time — a password or key passphrase
/// (`echo` false: masked), or a login name (`echo` true) — reusing the
/// keyboard-interactive prompt channel + modal. Emits a single prompt under
/// `kbi-prompt-{session_id}`, waits on `kbi_txs` keyed by `nonce` (the same
/// 120s budget as a real 2FA prompt), dismisses the modal, and returns the
/// typed value (zeroised) or `None` on cancel / timeout / dropped channel. The
/// value is never logged or persisted.
async fn prompt_for_secret(
    ctx: &SecretPromptCtx<'_>,
    label: &str,
    instructions: &str,
    echo: bool,
) -> Option<zeroize::Zeroizing<String>> {
    prompt_for_secret_offering_save(ctx, label, instructions, echo, None).await.map(|(value, _)| value)
}

/// `prompt_for_secret`, with a "Save password" tick when `offer_save` (on or
/// off to start with, as it says); the answer comes with whether it was left
/// ticked. Nothing is saved here: the caller saves the password once the login
/// with it worked.
async fn prompt_for_secret_offering_save(
    ctx: &SecretPromptCtx<'_>,
    label: &str,
    instructions: &str,
    echo: bool,
    offer_save: Option<SaveTarget>,
) -> Option<(zeroize::Zeroizing<String>, bool)> {
    use tauri::Emitter;
    // Superseded or abandoned attempt: never show its prompt over a newer
    // one. It ends the same way a cancelled prompt does.
    if !ctx.attempt.may_prompt().await {
        ctx.cancelled.store(true, std::sync::atomic::Ordering::Relaxed);
        return None;
    }
    let (tx, rx) = tokio::sync::oneshot::channel::<Option<Vec<String>>>();
    ctx.kbi_txs.lock().await.insert(ctx.nonce.to_string(), tx);
    let mut payload = serde_json::json!({
        "nonce": ctx.nonce,
        // Blank name keeps the modal's generic heading; the label carries
        // the meaning. Instructions only explain a retry.
        "name": "",
        "instructions": instructions,
        "prompts": [{ "prompt": label, "echo": echo }],
    });
    if let Some(to) = offer_save {
        payload["save"] = to.offer(ctx.app);
    }
    let _ = ctx.app.emit(&format!("kbi-prompt-{}", ctx.session_id), payload);
    let answer = match tokio::time::timeout(std::time::Duration::from_secs(120), rx).await {
        Ok(Ok(Some(mut answers))) => {
            // One prompt → one answer; ignore extras, treat a missing one as "".
            let first = if answers.is_empty() { String::new() } else { answers.swap_remove(0) };
            let save = offer_save.is_some() && take_save_choice(ctx.app, ctx.nonce).await;
            Some((zeroize::Zeroizing::new(first), save))
        }
        // Cancelled (None), timed out, or the sender was dropped.
        _ => {
            ctx.cancelled.store(true, std::sync::atomic::Ordering::Relaxed);
            None
        }
    };
    ctx.kbi_txs.lock().await.remove(ctx.nonce);
    // The nonce lets the tab ignore this if a newer prompt is already showing.
    let _ = ctx.app.emit(
        &format!("kbi-prompt-dismiss-{}", ctx.session_id),
        serde_json::json!({ "nonce": ctx.nonce }),
    );
    answer
}

/// The login name for a typed "Login as" answer: trimmed, and empty means
/// `root` — the long-standing default for a node saved without a username, so
/// pressing Enter logs in exactly as before.
fn login_user_from_answer(answer: &str) -> zeroize::Zeroizing<String> {
    let name = answer.trim();
    zeroize::Zeroizing::new(if name.is_empty() { "root".to_string() } else { name.to_string() })
}

/// The login name for a connection whose saved username may be blank (issue
/// #54). A saved name is used as-is. A blank one is taken from what the user
/// typed earlier in this tab, else asked for — "Login as", visible like
/// PuTTY's — on a primary connection. A dedicated `::sftp` / `::fwd`
/// connection never asks; with nothing cached it keeps the old `root` default.
///
/// Returns the name and whether it was typed just now (the caller caches a
/// typed name only once the login succeeds), or `None` when the prompt was
/// cancelled or timed out (`ctx.cancelled` is then set, so the attempt ends as
/// "Login cancelled"). The name is held in `Zeroizing` memory throughout.
async fn resolve_login_user(
    saved: &str,
    host: &str,
    slot: SecretSlot,
    ctx: &SecretPromptCtx<'_>,
) -> Option<(zeroize::Zeroizing<String>, bool)> {
    let saved = saved.trim();
    if !saved.is_empty() {
        return Some((zeroize::Zeroizing::new(saved.to_string()), false));
    }
    if let Some(cached) = cache_get_secret(ctx.cache, ctx.base, slot).await.filter(|u| !u.is_empty()) {
        return Some((cached, false));
    }
    if !ctx.allow_prompt {
        return Some((zeroize::Zeroizing::new("root".to_string()), false));
    }
    ctx.log("No saved username — asking for it.", "info");
    let typed = prompt_for_secret(
        ctx,
        &format!("Login as (on {})", host),
        "Leave it empty to log in as root.",
        true,
    )
    .await;
    match typed {
        Some(answer) => Some((login_user_from_answer(&answer), true)),
        None => {
            ctx.log("Username prompt cancelled or timed out.", "error");
            None
        }
    }
}

/// Password authentication for a login whose password may not be saved (issue
/// #30). Tries the passwords already in hand (`secret_candidates`), then — on a
/// primary connection, while the server still offers password auth — asks the
/// user, re-asking on rejection for up to `MAX_SECRET_PROMPTS` prompts. A typed
/// or cached password that is accepted is kept in the tab's cache under `slot`;
/// a cached one that is rejected is dropped.
///
/// With nothing in hand, a `none` probe first checks that the server offers
/// password auth at all, so a keyboard-interactive-only (2FA) server shows no
/// password box. `Ok(false)` — password not offered, prompt cancelled or timed
/// out, or prompts used up — leaves the caller's keyboard-interactive fallback
/// to run exactly as before.
async fn authenticate_password_prompting<H: russh::client::Handler>(
    session: &mut russh::client::Handle<H>,
    user: &str,
    host: &str,
    override_password: Option<zeroize::Zeroizing<String>>,
    saved_password: Option<zeroize::Zeroizing<String>>,
    slot: SecretSlot,
    ctx: &SecretPromptCtx<'_>,
) -> Result<bool, russh::Error> {
    let cached = cache_get_secret(ctx.cache, ctx.base, slot).await;
    let candidates = secret_candidates(override_password, cached, saved_password);
    let nothing_in_hand = candidates.is_empty();
    let mut candidates = candidates.into_iter();
    let mut password_offered = true;
    let mut rejected = false;
    let mut prompts_used: u32 = 0;
    // The last typed password was ticked "Save password".
    let mut save_typed = false;

    if nothing_in_hand {
        // An ssh-agent on this device may log in without asking for anything.
        // Looking for one is local and quick, and only happens here, where the
        // alternative is a prompt (or, on a connection that can't prompt,
        // giving up). Without an agent this is exactly as before.
        let agent_ready = device_keys_available(ctx).await;
        if !ctx.allow_prompt && !agent_ready {
            return Ok(false);
        }
        let publickey_offered;
        match session.authenticate_none(user).await? {
            russh::client::AuthResult::Success => return Ok(true),
            // russh also reports a dropped connection as a Failure (with no
            // methods left): that's a transport error, not "no passwords".
            russh::client::AuthResult::Failure { .. } if session.is_closed() => {
                return Err(russh::Error::Disconnect);
            }
            russh::client::AuthResult::Failure { remaining_methods, .. } => {
                password_offered = remaining_methods.contains(&russh::MethodKind::Password);
                publickey_offered = remaining_methods.contains(&russh::MethodKind::PublicKey);
            }
        }
        if agent_ready && publickey_offered {
            match try_agent_keys(session, user, agent_auth::Offer::Rest, None, ctx).await? {
                Some(agent_auth::AgentOutcome::Authenticated) => return Ok(true),
                // The key counted; finish with a password if that's what the
                // server wants next.
                Some(agent_auth::AgentOutcome::PartialSuccess { remaining }) => {
                    password_offered = remaining.contains(&russh::MethodKind::Password);
                }
                _ => {}
            }
        }
        if !ctx.allow_prompt {
            return Ok(false);
        }
    }

    loop {
        let (password, source) = match candidates.next() {
            Some(candidate) => candidate,
            None => {
                if !ctx.allow_prompt || !password_offered || prompts_used >= MAX_SECRET_PROMPTS {
                    return Ok(false);
                }
                if prompts_used == 0 {
                    ctx.log(
                        if rejected { "Password rejected — asking for it." } else { "No saved password — asking for it." },
                        "info",
                    );
                }
                let instructions = if rejected { "The password was rejected. Please try again." } else { "" };
                match prompt_for_secret_offering_save(ctx, &format!("Password for {}@{}", user, host), instructions, false, ctx.save_offer().await).await {
                    Some((typed, save)) => {
                        prompts_used += 1;
                        save_typed = save;
                        (typed, SecretSource::Prompt)
                    }
                    None => {
                        ctx.log("Password prompt cancelled or timed out.", "error");
                        return Ok(false);
                    }
                }
            }
        };
        match session.authenticate_password(user, password.as_str()).await? {
            russh::client::AuthResult::Success => {
                // Typed, ticked "Save password", and it worked: saved now.
                if source == SecretSource::Prompt && save_typed {
                    if let Some(to) = ctx.save_to {
                        match save_prompted_password(ctx.app, to, password.as_str()).await {
                            Ok(to) => ctx.log(&format!("Password saved to {to}."), "success"),
                            Err(e) => ctx.log(&format!("The password wasn't saved: {e}"), "error"),
                        }
                    }
                }
                if source != SecretSource::Given {
                    cache_store_secret(ctx.cache, ctx.base, slot, password).await;
                }
                return Ok(true);
            }
            // The connection dropped while the password was in flight — russh
            // reports that as a Failure too. Not a rejection: keep the cached
            // password and let the caller treat it as a transport error.
            russh::client::AuthResult::Failure { .. } if session.is_closed() => {
                return Err(russh::Error::Disconnect);
            }
            russh::client::AuthResult::Failure { remaining_methods, partial_success } => {
                if partial_success {
                    // Password accepted, but the server wants another factor
                    // (keyboard-interactive): keep it for reconnects and let the
                    // caller's 2FA fallback finish the login. The password itself
                    // was right, so a ticked one is saved.
                    if source == SecretSource::Prompt && save_typed {
                        if let Some(to) = ctx.save_to {
                            match save_prompted_password(ctx.app, to, password.as_str()).await {
                                Ok(to) => ctx.log(&format!("Password saved to {to}."), "success"),
                                Err(e) => ctx.log(&format!("The password wasn't saved: {e}"), "error"),
                            }
                        }
                    }
                    if source != SecretSource::Given {
                        cache_store_secret(ctx.cache, ctx.base, slot, password).await;
                    }
                    return Ok(false);
                }
                if source == SecretSource::Cache {
                    cache_clear_secret(ctx.cache, ctx.base, slot).await;
                }
                password_offered = remaining_methods.contains(&russh::MethodKind::Password);
                rejected = true;
            }
        }
    }
}

/// Private-key authentication for a key whose passphrase may not be saved
/// (issue #30). Decodes with the passphrases already in hand
/// (`secret_candidates`) — or with none, when there are none, since a plain
/// key needs none — then, on a primary connection, asks the user, re-asking
/// for up to `MAX_SECRET_PROMPTS` prompts while the passphrase doesn't decrypt
/// the key. Decrypting the key is the acceptance: a typed or cached passphrase
/// that does is kept in the tab's cache under `slot`; a cached one that
/// doesn't is dropped.
///
/// Without a usable passphrase (prompt cancelled or timed out, prompts used up,
/// or prompting not allowed) it returns `keys::Error::KeyIsEncrypted`, which
/// `classify_russh_error` buckets as an auth failure — so an auto-reconnect
/// stops instead of looping straight back into the prompt. A malformed or
/// unsupported key keeps the error shape the old inline decode produced. Either
/// way the caller's keyboard-interactive fallback still runs.
async fn authenticate_key_prompting<H: russh::client::Handler>(
    session: &mut russh::client::Handle<H>,
    user: &str,
    private_key: &str,
    key_label: &str,
    saved_passphrase: Option<zeroize::Zeroizing<String>>,
    slot: SecretSlot,
    ctx: &SecretPromptCtx<'_>,
) -> Result<bool, russh::Error> {
    let cached = cache_get_secret(ctx.cache, ctx.base, slot).await;
    let mut candidates = secret_candidates(None, cached, saved_passphrase).into_iter();
    let mut attempt = candidates.next();
    let mut rejected = false;
    let mut prompts_used: u32 = 0;
    let mut agent_checked = false;

    loop {
        match decode_private_key(private_key, attempt.as_ref().map(|(p, _)| p.as_str())) {
            Ok(keypair) => {
                if let Some((passphrase, source)) = attempt {
                    if source != SecretSource::Given {
                        cache_store_secret(ctx.cache, ctx.base, slot, passphrase).await;
                    }
                }
                let own_key = keypair.public_key().clone();
                return match ssh_manager::authenticate_with_key_result(session, user, keypair).await? {
                    russh::client::AuthResult::Success => Ok(true),
                    // The node's key was turned down. If the server still
                    // takes public keys, try the other keys an ssh-agent on
                    // this device holds.
                    russh::client::AuthResult::Failure { remaining_methods, partial_success: false }
                        if !session.is_closed() && remaining_methods.contains(&russh::MethodKind::PublicKey) =>
                    {
                        agent_keys_after(session, user, Some(&own_key), ctx).await
                    }
                    // Accepted with a second factor to follow (the
                    // keyboard-interactive fallback takes it), public keys no
                    // longer offered, or the connection dropped: as before.
                    russh::client::AuthResult::Failure { .. } => Ok(false),
                };
            }
            Err(KeyDecodeError::NeedsPassphrase) => {
                if let Some((_, source)) = &attempt {
                    if *source == SecretSource::Cache {
                        cache_clear_secret(ctx.cache, ctx.base, slot).await;
                    }
                    rejected = true;
                }
                if let Some(next) = candidates.next() {
                    attempt = Some(next);
                    continue;
                }
                // Before asking for the passphrase (or giving up for want of
                // one): an ssh-agent on this device may hold this very key
                // unlocked. Checked once, ahead of the first prompt.
                if !agent_checked {
                    agent_checked = true;
                    if let Some(own_key) = agent_auth::key_file_public_key(private_key) {
                        match try_agent_keys(session, user, agent_auth::Offer::Only(&own_key), None, ctx).await? {
                            Some(agent_auth::AgentOutcome::Authenticated) => return Ok(true),
                            Some(agent_auth::AgentOutcome::PartialSuccess { .. }) => return Ok(false),
                            Some(agent_auth::AgentOutcome::NotAccepted) => {
                                // The server turned this key down; unlocking the
                                // file would only offer it again. Try the agent's
                                // other keys instead of asking.
                                ctx.log(
                                    "The server didn't accept this key (checked through the ssh-agent), so its passphrase isn't asked for.",
                                    "info",
                                );
                                return agent_keys_after(session, user, None, ctx).await;
                            }
                            Some(agent_auth::AgentOutcome::NothingToOffer) | None => {}
                        }
                    }
                }
                if !ctx.allow_prompt || prompts_used >= MAX_SECRET_PROMPTS {
                    ctx.log("Key is passphrase-protected and no correct passphrase was supplied.", "error");
                    return Err(russh::Error::from(russh::keys::Error::KeyIsEncrypted));
                }
                if prompts_used == 0 {
                    ctx.log(
                        if rejected {
                            "Passphrase didn't unlock the key — asking for it."
                        } else {
                            "Key is passphrase-protected — asking for the passphrase."
                        },
                        "info",
                    );
                }
                let instructions = if rejected { "The passphrase didn't unlock the key. Please try again." } else { "" };
                match prompt_for_secret(ctx, &format!("Passphrase for key '{}'", key_label), instructions, false).await {
                    Some(typed) => {
                        prompts_used += 1;
                        attempt = Some((typed, SecretSource::Prompt));
                    }
                    None => {
                        ctx.log("Passphrase prompt cancelled or timed out.", "error");
                        return Err(russh::Error::from(russh::keys::Error::KeyIsEncrypted));
                    }
                }
            }
            Err(KeyDecodeError::Malformed(msg)) => {
                ctx.log(&format!("Failed to parse private key: {}", msg), "error");
                return Err(russh::Error::from(std::io::Error::new(
                    std::io::ErrorKind::InvalidData,
                    msg,
                )));
            }
        }
    }
}

